  const rejects=[['absent',{}],['disabled',{...armMode(),enabled:{BOOL:false}}],['scope',{...armMode(),scope:{S:'unknown'}}],['approval',{...armMode(),approvalRef:{S:''}}],['whitespace',{...armMode(),approvalRef:{S:'   '}}],['expired',{...armMode(),armedUntil:{S:new Date(fixed-1).toISOString()}}],['over4h',{...armMode(),armedUntil:{S:new Date(fixed+14400001).toISOString()}}]];
