// The On-Demand boot race. Scripted invocations follow the ssm_runtime.py main() contract; a real invocation shape is NOT VERIFIED.
export const notReady=(code='convergence-in-progress')=>({Status:'Failed',ResponseCode:75,StandardOutputContent:'NOT_READY '+code+'\n',StandardErrorContent:'failed to run commands: exit status 75'});
export const readyResult=()=>({Status:'Success',ResponseCode:0,StandardOutputContent:'{"result": "PASS"}\n'});
export const hostFailure=(code=1,output='')=>({Status:'Failed',ResponseCode:code,StandardOutputContent:output,StandardErrorContent:'FAIL fixed-code'});
