export const prepareInput=()=>({trigger:'manual',scheduledTime:'manual-boot-race',action:'prepare'});
export const sent=(m,state='OdReadiness')=>m.calls.filter(x=>x.state===state).length;
export const afterFirstRead=(fn)=>{let reads=0;return async(state,m)=>{if(state==='OdReadinessRead'&&++reads===1)fn(m)}};
