 const oneBoot=(m)=>{assert.equal(m.writes.filter(x=>x.operation==='startInstances').length,1);assert.equal(m.store.get('day#2026-10-21').starts.N,'1')};
 await test('boot race: activating -> activating -> success attests and promotes once',async()=>{const m=prepareFixture([notReady(),notReady(),readyResult()]);const r=await run(m);assert.equal(r.status,'PASS',m.trace.join(','));assert.equal(sent(m),3);oneBoot(m);assert.equal(m.o.holder,OD);assert.ok(m.store.has('ready#'+OD));assert.equal(m.writes.filter(x=>x.operation==='startExecution'&&JSON.parse(x.args.Input).intent==='promote-od').length,1)});
 await test('boot race: a queued start job is the same bounded wait',async()=>{const m=prepareFixture([notReady('convergence-start-queued'),notReady(),readyResult()]);const r=await run(m);assert.equal(r.status,'PASS',m.trace.join(','));assert.equal(sent(m),3)});
 await test('boot race: every re-send passes its own fence',async()=>{const m=prepareFixture([notReady(),notReady(),readyResult()]);await run(m);const at=m.trace.flatMap((x,i)=>x==='OdReadiness'?[i]:[]);assert.equal(at.length,3);for(const i of at)assert.equal(m.trace[i-1],'FenceOdReadiness');const fence=doc().States.FenceOdReadiness.Arguments.TransactItems;assert.ok(fence.some(x=>x.ConditionCheck?.Key.pk.S==='maintenance'));assert.equal(fence.find(x=>x.ConditionCheck?.Key.pk.S==='mode').ConditionCheck.ExpressionAttributeValues[':s0'].S,'failover-prep');assert.ok(fence.some(x=>x.Update?.Key.pk.S==='lock#runtime'))});
 await test('boot race: activating until the recheck limit fails with no proof and no second boot',async()=>{const m=prepareFixture([notReady()]);const r=await run(m);noProof(r,m);assert.equal(sent(m),25);oneBoot(m);assert.equal(m.store.get('mode').state.S,'degraded')});
 await test('boot race: the recheck limit fits inside the boot deadline',async()=>{const d=doc().States;const wait=d.OdReadinessRecheckWait.Seconds+d.OdReadinessWait.Seconds;assert.equal(wait,40);assert.ok(24*wait<1200);assert.match(d.OdReadinessChoice.Choices[2].Condition,/\$odReadinessRechecks<24 and \$millis\(\)<\$odBootAt\+1200000/);assert.match(d.OdReadinessRecheckGate.Choices[0].Condition,/\$millis\(\)<\$odBootAt\+1200000/)});
