// Only the run that owns a transition may mark it degraded. Nested runs fail transiently on their own state while a prepare is under way.
export const failingRun=async(m,state,run)=>{const now=m.now,failAt=m.o.failAt,error=m.o.error;m.o.failAt=state;m.o.error='States.TaskFailed';const r=await run();m.o.failAt=failAt;m.o.error=error;const seen={status:r.status,error:r.error,mode:m.store.get('mode').state.S,lease:m.store.get('lock#runtime')?.owner?.S?.split(':').pop()};m.now=now;return seen};
// Two prepares both past the gate: the first takes the lease and the mode, the second gets the lease during the boot wait.
export async function racingPrepares(first=readDoc('od-standby'),second=readDoc('od-standby')){let release,arrived,running;const released=new Promise(r=>{release=r}),atBootstrap=new Promise(r=>{arrived=r});
 const m=raceFixture([readyResult()],{},{holder:raceSpot,midHook:async(state,m)=>{if(state==='FailoverMode'&&!running){running=replay(second,m,{trigger:'manual',scheduledTime:'manual-second-prepare',action:'prepare',reason:'guard-signal'},3000,'second');await atBootstrap}else if(state==='Bootstrap'&&running&&!m.waited){m.waited=true;arrived();await released}else if(state==='PollBoot'&&!m.released){m.released=true;release();m.second=await running;m.afterSecond=m.store.get('mode').state.S;m.leaseAfterSecond=m.store.has('lock#runtime')}else if(state==='ReadOdPromotion'&&!m.promoted){m.promoted=true;m.o.spotState='shutting-down';await guardPromote(m)}}});
 const firstResult=await replay(first,m,prepareInput(),3000,'first');return {m,firstResult,secondResult:m.second}}
